.messages-timeline-scroll{background:transparent!important}
[data-message-role="assistant"] .chat-markdown{background:rgba(12,3,24,.58)!important;backdrop-filter:blur(18px) saturate(150%)!important;-webkit-backdrop-filter:blur(18px) saturate(150%)!important;border:1px solid rgba(0,240,255,.28);border-radius:16px;padding:14px 18px;box-shadow:0 8px 32px rgba(0,0,0,.4),inset 0 0 24px rgba(255,43,214,.06);text-shadow:0 1px 2px rgba(0,0,0,.6)}
[data-timeline-row-kind]:not([data-timeline-row-kind="message"]),[data-message-role="assistant"] details{background:rgba(12,3,24,.58)!important;backdrop-filter:blur(18px) saturate(150%)!important;-webkit-backdrop-filter:blur(18px) saturate(150%)!important;border:1px solid rgba(255,43,214,.25);border-radius:14px;text-shadow:0 1px 2px rgba(0,0,0,.6)}
[data-slot="composer-host"]{background:rgba(12,3,24,.58)!important;backdrop-filter:blur(18px) saturate(150%)!important;-webkit-backdrop-filter:blur(18px) saturate(150%)!important;}
[data-chat-header]{background:linear-gradient(90deg,#8a0f72,#3d1290 50%,#0b5470)!important;color:#fff!important;border-bottom:2px solid #ff2bd6!important;box-shadow:0 2px 24px rgba(255,43,214,.5)}
[data-chat-header] *{color:#fff!important;text-shadow:0 1px 3px rgba(0,0,0,.85)}
[data-chat-header] svg.lucide{color:#fff!important;stroke:#fff!important}
[data-user-message-bubble]{background:linear-gradient(135deg,#ff2bd6,#7b2bff)!important;color:#fff!important;border:none!important;border-radius:18px 18px 4px 18px!important;box-shadow:0 0 18px rgba(255,43,214,.6),0 0 40px rgba(123,43,255,.35)!important}
.chat-markdown h1,.chat-markdown h2,.chat-markdown h3{color:#00f0ff!important;text-shadow:0 0 10px rgba(0,240,255,.7)}
.chat-markdown a{color:#ff2bd6!important;text-shadow:0 0 6px rgba(255,43,214,.6)}
.chat-markdown-codeblock{border:1px solid #00f0ff!important;border-radius:10px!important;box-shadow:0 0 14px rgba(0,240,255,.35),inset 0 0 20px rgba(0,240,255,.06)!important}
[data-slot="composer-host"]{border:2px solid #ff2bd6!important;border-radius:16px!important;box-shadow:0 0 22px rgba(255,43,214,.55),0 0 60px rgba(0,240,255,.2)!important;animation:neonPulse 3s ease-in-out infinite}
@keyframes neonPulse{0%,100%{box-shadow:0 0 18px rgba(255,43,214,.5),0 0 50px rgba(0,240,255,.15)}50%{box-shadow:0 0 30px rgba(0,240,255,.6),0 0 70px rgba(255,43,214,.3)}}
@media (prefers-reduced-motion:reduce){[data-slot="composer-host"]{animation:none}}
[data-slot="sidebar-inner"]{background:linear-gradient(180deg,#1a0430,#0c0216 60%)!important;border-right:1px solid #ff2bd6!important;box-shadow:4px 0 20px rgba(255,43,214,.25)}
[data-thread-item]{border-radius:8px!important;transition:transform .15s,box-shadow .15s}
[data-thread-item]:hover{transform:translateX(3px);box-shadow:inset 3px 0 0 #00f0ff,0 0 12px rgba(0,240,255,.25)}
[data-slot="project-monogram"]{filter:drop-shadow(0 0 6px #ff2bd6) hue-rotate(20deg)}
[data-slot="button"]{border-radius:10px!important;transition:box-shadow .15s,transform .1s}
[data-slot="button"]:hover{box-shadow:0 0 12px rgba(0,240,255,.55)!important}
[data-slot="button"]:active{transform:scale(.96)}
[data-slot="dialog-popup"],[data-slot="popover-popup"],[data-slot="menu-popup"]{border:1px solid #ff2bd6!important;box-shadow:0 0 30px rgba(255,43,214,.45)!important}
[data-slot="tooltip-popup"]{background:#00f0ff!important;color:#12051f!important;font-weight:600}
::selection{background:#ff2bd6;color:#fff}
::-webkit-scrollbar{width:10px;height:10px}
::-webkit-scrollbar-thumb{background:linear-gradient(#ff2bd6,#00f0ff);border-radius:10px}
[data-slot="scroll-area-thumb"]{background:linear-gradient(#ff2bd6,#00f0ff)!important}
svg.lucide{stroke-width:2.25}
